#!/usr/bin/env node
// Builds the engine bundle the iOS app's Bubble runtime loads:
//   FacebookClone/Bubbles/Runtime/web/bubble-kit-microgame-engine.js
//
// It's one classic (non-module) script: engine/web/microgame.js and
// engine/web/render.js with their imports and exports stripped, plus the WASM
// bytes as base64, wrapped in an IIFE that defines `MicrogameEngine`. The app
// loads the page with loadFileURL, where fetch() of a .wasm file isn't
// reliable, and the runtime's API is synchronous, so the module is compiled
// synchronously from these bytes the first time a microgame plays.
//
// Usage (from engine/): ./build-wasm.sh && node tools/make-app-bundle.mjs [--check]
//   --check: exit 1 if the committed bundle differs from a fresh build.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execSync } from 'node:child_process';

const engineDir = join(dirname(fileURLToPath(import.meta.url)), '..');
const out = join(engineDir, '..', 'FacebookClone', 'Bubbles', 'Runtime', 'web', 'bubble-kit-microgame-engine.js');
const wasmPath = join(engineDir, 'web', 'pkg', 'microgame.wasm');
const check = process.argv.includes('--check');

if (!existsSync(wasmPath)) {
  console.error(`missing ${wasmPath}: run ./build-wasm.sh first`);
  process.exit(2);
}

/** ES module source → plain declarations for the shared IIFE scope. */
function strip(src, name) {
  let s = src
    .replace(/^import[^;]*;\s*$/gm, '')
    .replace(/^export (class|function|const|let|async function) /gm, '$1 ')
    .replace(/new URL\('\.\/pkg\/microgame\.wasm', import\.meta\.url\)/g, 'undefined');
  if (/\bimport\.meta\b|^\s*export\b/m.test(s)) throw new Error(`${name}: leftover module syntax`);
  return `// ---- ${name} ----\n${s.trim()}\n`;
}

const wasm = readFileSync(wasmPath);
const sha = createHash('sha256').update(wasm).digest('hex');
let commit = 'unknown';
try { commit = execSync('git rev-parse --short HEAD', { cwd: engineDir }).toString().trim(); } catch { /* not a checkout */ }

const body = [
  strip(readFileSync(join(engineDir, 'web', 'microgame.js'), 'utf8'), 'engine/web/microgame.js'),
  strip(readFileSync(join(engineDir, 'web', 'render.js'), 'utf8'), 'engine/web/render.js'),
].join('\n');

const bundle = `/*
 * bubble-kit-microgame-engine.js: GENERATED by engine/tools/make-app-bundle.mjs. Do not edit.
 * The microgame engine (Rust compiled to WebAssembly) for the Bubble runtime, plus its frame
 * renderer. Defines \`MicrogameEngine\`; bubble-kit-microgame.js turns it into the "microgame"
 * formula (docs/BUBBLES.md, "microgame").
 * Built from engine/ at ${commit}; microgame.wasm ${wasm.length} bytes, sha256 ${sha}.
 */
(function (root) {
  "use strict";
  if (root.MicrogameEngine) return;

  // JavaScriptCore contexts may lack TextEncoder/TextDecoder: minimal UTF-8 versions.
  const TextEncoder = root.TextEncoder || class {
    encode(str) {
      const s = unescape(encodeURIComponent(String(str)));
      const out = new Uint8Array(s.length);
      for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
      return out;
    }
  };
  const TextDecoder = root.TextDecoder || class {
    decode(bytes) {
      let s = '';
      for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
      return decodeURIComponent(escape(s));
    }
  };

${body}
  const WASM_BASE64 = "${wasm.toString('base64')}";

  function decodeBase64(b64) {
    const map = new Uint8Array(128);
    const abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    for (let i = 0; i < abc.length; i++) map[abc.charCodeAt(i)] = i;
    let n = b64.length;
    while (n > 0 && b64[n - 1] === "=") n--;
    const out = new Uint8Array((n * 3) >> 2);
    let o = 0, buf = 0, bits = 0;
    for (let i = 0; i < n; i++) {
      buf = (buf << 6) | map[b64.charCodeAt(i)];
      bits += 6;
      if (bits >= 8) { bits -= 8; out[o++] = (buf >> bits) & 0xff; }
    }
    return out;
  }

  let engine = null;
  let engineError = null;
  /** The engine, compiled on first use; null where WebAssembly is unavailable. */
  function getEngine() {
    if (engine || engineError) return engine;
    if (typeof WebAssembly === "undefined") { engineError = "WebAssembly is not available here"; return null; }
    try {
      engine = Microgame.initSync(decodeBase64(WASM_BASE64));
    } catch (e) {
      engineError = "engine failed to start: " + (e && e.message ? e.message : String(e));
    }
    return engine;
  }

  /**
   * Replays a run's input log (microgame-log/1) against the exact game text and checks the result
   * it claims: {ok, game_hash_ok, steps, recomputed, claimed, problems, result}. result is the end
   * values of the state named in state (group_play.result.state), or all of the game's state.
   */
  function verify(gameText, log, state) {
    const e = getEngine();
    if (!e) return { ok: false, game_hash_ok: false, steps: 0, recomputed: null, claimed: null, problems: [engineError || "engine unavailable"] };
    return e.verify(gameText, log, state);
  }

  root.MicrogameEngine = Object.freeze({
    getEngine,
    verify,
    engineError: () => engineError,
    Microgame, Game, MicrogameLoadError, MicrogameCrash,
    decodeFrame, rgbaToCss, rgbaToHex,
    drawFrame, playSound, MusicPlayer, AssetStore, HAPTIC_PATTERNS,
    build: Object.freeze({ commit: ${JSON.stringify(commit)}, wasm_bytes: ${wasm.length}, wasm_sha256: ${JSON.stringify(sha)} }),
  });
})(typeof globalThis !== "undefined" ? globalThis : this);
`;

if (check) {
  const cur = existsSync(out) ? readFileSync(out, 'utf8') : '';
  // Ignore the commit stamp: the bundle is committed in the same change as its sources.
  const norm = (s) => s.replace(/Built from engine\/ at \S+;/, '').replace(/commit: "[^"]*"/, '');
  if (norm(cur) !== norm(bundle)) {
    console.error(`${out} is out of date: run engine/build-wasm.sh && node engine/tools/make-app-bundle.mjs`);
    process.exit(1);
  }
  console.log('app bundle is up to date');
} else {
  writeFileSync(out, bundle);
  console.log(`wrote ${out}: ${(bundle.length / 1024).toFixed(0)} KiB (wasm ${(wasm.length / 1024).toFixed(0)} KiB, sha256 ${sha.slice(0, 12)})`);
}
